import numpy as np
def T(t,N=25,nu=3):
    r=np.arange(-N,N+1);a,b=np.meshgrid(r,r);a=a.ravel();b=b.ravel()
    m=(a!=0)|(b!=0);a=a[m];b=b[m]
    s=np.sqrt(t.imag);X=(a+b*t)/s
    d=np.abs(X)
    D=np.abs(X[:,None]-X[None,:]);np.fill_diagonal(D,np.inf)
    return (d[:,None]*d[None,:]*D)**(-nu)
def E(t):return T(t,12).sum()
